 if sys.flags.optimize:raise RuntimeError("Proof launcher requires Python assertions enabled")
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--plan',action='store_true');p.add_argument('--self-test',action='store_true');p.add_argument('--prepare',action='store_true');p.add_argument('--execute-browser',action='store_true');p.add_argument('--cache',type=Path,default=Path('scheduler-core-cache'));p.add_argument('--private',type=Path,default=Path('scheduler-core-output'));p.add_argument('--extract-only',action='store_true');p.add_argument('--validate-report',type=Path);p.add_argument('--validate-public-build',type=Path);p.add_argument('--render-report',type=Path);p.add_argument('--build-proof',type=Path);p.add_argument('--html-output',type=Path);p.add_argument('--ci-start-monotonic',type=float);a=p.parse_args()
 if a.prepare or a.execute_browser:
  # Never let a failed new attempt validate/upload an older scalar receipt.
  for stale in (a.private/'public-build.json',a.private/'browser/browser-report.json',a.private/'report.html'):
   if stale.is_symlink():raise ValueError('Refusing symlink receipt target')
   stale.unlink(missing_ok=True)
 preflight_start=launcher_start if a.ci_start_monotonic is None else a.ci_start_monotonic
 if not math.isfinite(preflight_start) or preflight_start<0 or preflight_start>launcher_start:raise ValueError('Invalid or future monotonic preflight start')
 preflight_origin='standalone_launcher' if a.ci_start_monotonic is None else 'ci_first_step'
 root=unpack(a.private/('source-'+PAYLOAD_SHA256[:12]));env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',SCHEDULER_CORE_LAUNCHER_PATH=str(Path(__file__).resolve()))
 def run(*args):subprocess.run([sys.executable,*map(str,args)],cwd=root,env=env,check=True)
