  run('-m','unittest','discover','-s','tools','-p','test_*.py','-v');run('-m','unittest','discover','-s','workflow','-p','test_*.py','-v');run('-m','unittest','discover','-s','browser/tests','-p','test_*.py','-v');run('-m','unittest','discover','-s','tests','-p','test_*.py','-v')
